                        onClick={() => setIsLoopLyrics(!isLoopLyrics)}
                        disabled={isFnfMode}
                        className={`flex-1 py-2 px-3 rounded-lg border text-xs font-bold flex items-center justify-center gap-2 transition-all ${isLoopLyrics && !isFnfMode ? 'bg-synth-pop/20 border-synth-pop text-synth-pop' : 'bg-slate-800 border-transparent text-slate-500 hover:border-slate-600'} ${isFnfMode ? 'opacity-50' : ''}`}
                     >
                         <Repeat size={14}/> LOOP TEXT
                     </button>
                </div>

                {isFnfMode ? (
                    <div className="h-32 bg-slate-900 rounded-xl border border-dashed border-orange-500/30 flex flex-col items-center justify-center text-center p-4">
                        <p className="text-orange-400 font-bold text-sm mb-1">FNF Pattern Active</p>
                        <p className="text-[10px] text-slate-400">Maps vowels to pitch relative to C4:</p>
                        <div className="flex gap-1 mt-2 font-mono text-xs">
                            <span className="bg-slate-800 px-1 rounded text-white">U</span>
                            <span className="bg-slate-800 px-1 rounded text-white">O</span>
                            <span className="bg-slate-800 px-1 rounded text-white">A</span>
                            <span className="bg-slate-800 px-1 rounded text-white">E</span>
                            <span className="bg-slate-800 px-1 rounded text-white">I</span>
                        </div>
                    </div>
                ) : (
                    <textarea 
                        className="w-full h-32 bg-synth-dark border border-synth-grid rounded-xl p-3 text-white focus:border-synth-accent outline-none font-mono text-sm" 
                        placeholder="Paste lyrics to syllabify..." 
                        value={lyricsInput} 
                        onChange={(e) => setLyricsInput(e.target.value)} 
                    />
                )}

                <button onClick={handleApplyLyrics} className="flex-1 py-3 rounded-xl text-xs font-bold bg-synth-accent text-synth-dark flex items-center justify-center gap-2 hover:bg-white transition-colors"><Check size={14} /> {isFnfMode ? 'GENERATE PATTERN' : 'APPLY TO TRACK'}</button>
            </div>
        </div>
      )}

      {showPitchModal && (
        <div className="absolute inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-synth-panel border border-synth-grid rounded-2xl w-full max-w-sm p-4 shadow-2xl flex flex-col gap-3">
                <div className="flex justify-between items-center border-b border-synth-grid pb-2"><h3 className="text-sm font-bold text-white flex items-center gap-2"><TrendingUp size={16} className="text-synth-pop" /> PITCH BEND</h3><button onClick={() => setShowPitchModal(false)}><X size={18} className="text-slate-400"/></button></div>
                <div className="relative w-full h-40 bg-synth-dark rounded-lg border border-synth-grid overflow-hidden cursor-crosshair"><canvas ref={pitchCanvasRef} width={340} height={160} onClick={handlePitchCanvasClick} className="w-full h-full"/><div className="absolute top-1/2 left-0 right-0 h-px bg-slate-600/50 pointer-events-none"/></div>
                <div className="flex gap-2 justify-center"><button onClick={() => setPitchCurve([{t:0,v:0},{t:1,v:0}])} className="text-[10px] px-2 py-1 bg-slate-700 rounded text-slate-300">FLAT</button><button onClick={() => setPitchCurve([{t:0,v:0},{t:1,v:5}])} className="text-[10px] px-2 py-1 bg-slate-700 rounded text-slate-300">RISE</button><button onClick={() => setPitchCurve([{t:0,v:0},{t:1,v:-5}])} className="text-[10px] px-2 py-1 bg-slate-700 rounded text-slate-300">FALL</button></div>
                <button onClick={handleApplyPitch} className="flex-1 py-2 rounded-xl text-xs font-bold bg-synth-pop text-white flex items-center justify-center gap-2"><Check size={14} /> APPLY</button>
            </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React, { useRef, useState, useEffect } from 'react';
import { SequencerNote, SequencerTrack } from '../types';
import { 
  Pencil, Eraser, Undo, Redo, Trash2, MousePointer2, Hand, 
  ArrowLeftRight, ArrowUp, ArrowDown, ArrowLeft, ArrowRight, TrendingUp
} from 'lucide-react';

interface PianoRollProps {
  notes: SequencerNote[];
  setNotes: React.Dispatch<React.SetStateAction<SequencerNote[]>>;
  ghostTracks?: SequencerTrack[]; // New prop for background notes
  durationBeats: number; // Total beats
  onUndo: () => void;
  onRedo: () => void;
  addToHistory: () => void;
  canUndo: boolean;
  canRedo: boolean;
  onEditPitch?: (noteId: string) => void;
}

const NOTE_HEIGHT = 20; // Compact height
const PIXELS_PER_BEAT = 60; // Zoom level
// Expanded Range: 0 (C-1) to 127 (G9) covers standard MIDI full range (~10.5 octaves)
const MIDI_MIN = 0; 
const MIDI_MAX = 127; 
const TOTAL_KEYS = MIDI_MAX - MIDI_MIN + 1;

type ToolType = 'POINTER' | 'PENCIL' | 'ERASER' | 'HAND';

export const PianoRoll: React.FC<PianoRollProps> = ({ 
  notes, setNotes, ghostTracks = [], durationBeats, onUndo, onRedo, addToHistory, canUndo, canRedo, onEditPitch
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [selectedNoteId, setSelectedNoteId] = useState<string | null>(null);
  const [tool, setTool] = useState<ToolType>('POINTER');

  // Interaction State
  const dragRef = useRef<{ 
    type: 'MOVE' | 'RESIZE' | 'PAN' | 'CREATE', 
    noteId?: string, 
    startX: number, 
    startY: number, 
    initialStart?: number, 
    initialMidi?: number, 
    initialDuration?: number,
    initialScrollX?: number,
    initialScrollY?: number
  } | null>(null);

  // Generate Keys Data
  const keys = [];
  for (let i = MIDI_MAX; i >= MIDI_MIN; i--) {
    const isBlack = [1, 3, 6, 8, 10].includes(i % 12);
    // Label Logic: i=0 -> C-1, i=12 -> C0, i=60 -> C4
    keys.push({ midi: i, isBlack, label: i % 12 === 0 ? `C${(i/12)-1}` : '' });
  }

  // Auto-scroll to C4 on mount
  useEffect(() => {
    if (containerRef.current) {
        // Center C4 (Midi 60)
        const c4Midi = 60;
        const topPos = (MIDI_MAX - c4Midi) * NOTE_HEIGHT;
        const containerHeight = containerRef.current.clientHeight;
        // Scroll so C4 is roughly in the middle
        containerRef.current.scrollTop = topPos - (containerHeight / 2) + (NOTE_HEIGHT / 2);
    }
  }, []);

  // --- Helpers ---
  const getNoteAt = (midi: number, beat: number) => {
    return notes.find(n => 
      n.midi === midi && 
      beat >= n.startTime && 
      beat < n.startTime + n.duration
    );
  };

  const snapToGrid = (val: number, step = 0.25) => {
      return Math.round(val / step) * step;
  };

  // --- Handlers ---

  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();

    // Coordinates relative to the scroll container content
    // We must account for the sticky header (keys width)
    const KEYS_WIDTH = 48;
    const rawX = e.clientX - rect.left;
    const scrollX = containerRef.current.scrollLeft;
    const scrollY = containerRef.current.scrollTop;

    // Effective Grid Coordinates
    const gridX = rawX + scrollX - KEYS_WIDTH;
    const gridY = e.clientY - rect.top + scrollY;

    // Check bounds (don't click on keys column)
    if (rawX < KEYS_WIDTH && tool !== 'HAND') return;

    const beat = Math.max(0, gridX / PIXELS_PER_BEAT);
    const midi = MIDI_MAX - Math.floor(gridY / NOTE_HEIGHT);

    // --- TOOL LOGIC ---

    if (tool === 'HAND' || (e.button === 1)) { // Middle click or Hand tool
        dragRef.current = {
            type: 'PAN',
            startX: e.clientX,
            startY: e.clientY,
            initialScrollX: scrollX,
            initialScrollY: scrollY
        };
        return;
    }

    if (tool === 'ERASER') {
        const clickedNote = getNoteAt(midi, beat);
        if (clickedNote) {
            addToHistory();
            setNotes(prev => prev.filter(n => n.id !== clickedNote.id));
        }
        return;
    }

    if (tool === 'PENCIL') {
        const existing = getNoteAt(midi, beat);
        if (existing) {
            setSelectedNoteId(existing.id);
        } else {
            // Create
            addToHistory();
            const newNote: SequencerNote = {
                id: Math.random().toString(36).substr(2, 9),
                midi: midi,
                startTime: Math.floor(beat * 4) / 4, // Snap 1/4
                duration: 1.0,
                lyric: 'la',
                pitchPoints: [{t:0,v:0},{t:1,v:0}]
            };
            setNotes(prev => [...prev, newNote]);
            setSelectedNoteId(newNote.id);
            // Immediately start moving/resizing? Maybe just creation for now.
        }
        return;
    }

    if (tool === 'POINTER') {
        // We handle Note Click separately in onMouseDown on the Note element itself usually,
        // but if we clicked Empty Space, Deselect.
        const existing = getNoteAt(midi, beat);
        if (!existing) {
            setSelectedNoteId(null);
        }
    }
  };

  const handleNoteMouseDown = (e: React.MouseEvent, note: SequencerNote, type: 'MOVE' | 'RESIZE') => {
    e.stopPropagation();
    if (tool !== 'POINTER') return; // Only pointer modifies existing notes logic here

    addToHistory();
    setSelectedNoteId(note.id);

    dragRef.current = {
        type: type,
        noteId: note.id,
        startX: e.clientX,
        startY: e.clientY,
        initialStart: note.startTime,
        initialMidi: note.midi,
        initialDuration: note.duration
    };
  };

  const handleGlobalMove = (e: MouseEvent) => {
    if (!dragRef.current) return;
    const { type, startX, startY, noteId, initialStart, initialMidi, initialDuration, initialScrollX, initialScrollY } = dragRef.current;

    if (type === 'PAN' && containerRef.current) {
        const dx = e.clientX - startX;
        const dy = e.clientY - startY;
        containerRef.current.scrollLeft = (initialScrollX || 0) - dx;
        containerRef.current.scrollTop = (initialScrollY || 0) - dy;
        return;
    }

    const deltaX = (e.clientX - startX) / PIXELS_PER_BEAT;
    const deltaY = (e.clientY - startY) / NOTE_HEIGHT;

    if (type === 'MOVE') {
        const newStart = Math.max(0, snapToGrid((initialStart || 0) + deltaX));
        const newMidi = Math.min(MIDI_MAX, Math.max(MIDI_MIN, Math.round((initialMidi || 0) - deltaY)));

        setNotes(prev => prev.map(n => n.id === noteId ? { ...n, startTime: newStart, midi: newMidi } : n));
    }

    if (type === 'RESIZE') {
        const newDur = Math.max(0.125, snapToGrid((initialDuration || 0) + deltaX, 0.125));
        setNotes(prev => prev.map(n => n.id === noteId ? { ...n, duration: newDur } : n));
    }
  };

  const handleGlobalUp = () => {
    dragRef.current = null;
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleGlobalMove);
    window.addEventListener('mouseup', handleGlobalUp);
    return () => {
        window.removeEventListener('mousemove', handleGlobalMove);
        window.removeEventListener('mouseup', handleGlobalUp);
    };
  }, []);

  const updateNoteLyric = (id: string, newLyric: string) => {
    setNotes(notes.map(n => n.id === id ? { ...n, lyric: newLyric } : n));
  };

  const updateNoteDuration = (id: string, newDuration: number) => {
    if (isNaN(newDuration)) return;
    const d = Math.max(0.125, newDuration);
    setNotes(notes.map(n => n.id === id ? { ...n, duration: d } : n));
  };

  const deleteNote = (id: string) => {
      addToHistory();
      setNotes(notes.filter(n => n.id !== id));
      setSelectedNoteId(null);
  };

  const moveSelectedNote = (dt: number, dMidi: number) => {
    if (!selectedNoteId) return;
    addToHistory();
    setNotes(prev => prev.map(n => {
        if (n.id !== selectedNoteId) return n;
        const newStart = Math.max(0, n.startTime + dt);
        const newMidi = Math.min(MIDI_MAX, Math.max(MIDI_MIN, n.midi + dMidi));
        return { ...n, startTime: newStart, midi: newMidi };
    }));
  };

  return (
    <div className="flex flex-col h-full bg-gray-900 border border-synth-grid rounded-xl overflow-hidden select-none shadow-2xl relative group">

      {/* Toolbar */}
      <div className="bg-synth-panel p-2 flex gap-2 items-center border-b border-synth-grid shrink-0 z-30 relative overflow-x-auto no-scrollbar">
        <span className="text-xs font-bold text-synth-accent mr-2 hidden sm:block">TOOLS</span>

        <div className="flex bg-synth-dark rounded-lg p-0.5 border border-synth-grid shrink-0">
            <button onClick={() => setTool('POINTER')} className={`p-2 rounded-md ${tool === 'POINTER' ? 'bg-synth-accent text-synth-dark' : 'text-slate-400'}`} title="Select/Move/Resize">
                <MousePointer2 size={16} />
            </button>
            <button onClick={() => setTool('PENCIL')} className={`p-2 rounded-md ${tool === 'PENCIL' ? 'bg-synth-accent text-synth-dark' : 'text-slate-400'}`} title="Create">
                <Pencil size={16} />
            </button>
            <button onClick={() => setTool('HAND')} className={`p-2 rounded-md ${tool === 'HAND' ? 'bg-synth-accent text-synth-dark' : 'text-slate-400'}`} title="Navigate">
                <Hand size={16} />
            </button>
             <button onClick={() => setTool('ERASER')} className={`p-2 rounded-md ${tool === 'ERASER' ? 'bg-synth-pop text-white' : 'text-slate-400'}`} title="Erase">
                <Eraser size={16} />
            </button>
        </div>

        <div className="w-px h-6 bg-synth-grid mx-1 shrink-0"></div>

        <div className="flex gap-1 shrink-0">
             <button onClick={onUndo} disabled={!canUndo} className={`p-2 rounded-md ${canUndo ? 'text-slate-200 hover:bg-slate-700' : 'text-slate-700'}`}><Undo size={16} /></button>
            <button onClick={onRedo} disabled={!canRedo} className={`p-2 rounded-md ${canRedo ? 'text-slate-200 hover:bg-slate-700' : 'text-slate-700'}`}><Redo size={16} /></button>
        </div>

        {selectedNoteId && (
            <div className="flex items-center gap-2 ml-auto animate-in fade-in duration-200 border-l border-synth-grid pl-2 shrink-0">
                <button 
                    onClick={() => onEditPitch && onEditPitch(selectedNoteId)}
                    className="flex items-center gap-1 px-2 py-1 bg-synth-dark border border-synth-grid rounded text-[10px] text-synth-pop hover:bg-slate-700"
                    title="Edit Pitch Bend"
                >
                    <TrendingUp size={12} />
                    <span className="hidden sm:inline">PITCH</span>
                </button>
                <input 
                    type="text" 
                    className="bg-synth-dark border border-synth-grid rounded px-2 py-1 text-xs text-white w-20 focus:border-synth-pop outline-none text-center"
                    value={notes.find(n => n.id === selectedNoteId)?.lyric || ''}
                    onChange={(e) => updateNoteLyric(selectedNoteId, e.target.value)}
                    onFocus={addToHistory}
                    placeholder="Lyric"
                    title="Lyric"
                />

                {/* Manual Duration Control */}
                <div className="flex items-center bg-synth-dark border border-synth-grid rounded px-1" title="Duration (Beats)">
                    <ArrowLeftRight size={10} className="text-slate-500 mr-1" />
                    <input 
                        type="number"
                        step={0.25}
                        min={0.125}
                        className="bg-transparent text-xs text-white w-10 focus:outline-none text-center font-mono appearance-none"
                        value={notes.find(n => n.id === selectedNoteId)?.duration || 0}
                        onChange={(e) => updateNoteDuration(selectedNoteId, parseFloat(e.target.value))}
                        onFocus={addToHistory}
                    />
                </div>
            </div>
        )}
      </div>

      {/* Main Scroll Container */}
      <div 
        ref={containerRef}
        className={`flex-1 overflow-auto bg-synth-dark relative scroll-smooth ${tool === 'HAND' ? 'cursor-grab active:cursor-grabbing' : 'cursor-default'}`}
        onMouseDown={handleMouseDown}
      >
        <div 
            className="relative flex" 
            style={{ 
                height: `${TOTAL_KEYS * NOTE_HEIGHT}px`, 
                width: `${Math.max(durationBeats * PIXELS_PER_BEAT + 48, 1000)}px` // +48 for keys width
            }}
        >

            {/* STICKY KEYS COLUMN */}
            <div className="w-12 sticky left-0 z-20 bg-white border-r border-gray-300 flex flex-col shrink-0 shadow-lg">
                {keys.map((k) => (
                    <div 
                        key={k.midi} 
                        className={`h-[20px] border-b border-gray-300 text-[9px] flex items-center justify-end pr-1 font-bold ${k.isBlack ? 'bg-black text-white' : 'bg-white text-gray-800'}`}
                        style={{ height: NOTE_HEIGHT }}
                    >
                        {k.label}
                    </div>
                ))}
            </div>

            {/* GRID AREA */}
            <div className="flex-1 relative">

                {/* Background Rows */}
                {keys.map((k, i) => (
                    <div 
                        key={k.midi}
                        className={`absolute w-full border-b border-synth-grid/10 ${k.isBlack ? 'bg-synth-grid/5' : ''}`}
                        style={{ top: i * NOTE_HEIGHT, height: NOTE_HEIGHT }}
                    />
                ))}

                {/* Vertical Beat Lines */}
                {Array.from({ length: Math.ceil(durationBeats) + 1 }).map((_, i) => (
                    <div 
                        key={i} 
                        className={`absolute top-0 bottom-0 w-px ${i % 4 === 0 ? 'bg-synth-grid/60' : 'bg-synth-grid/20'}`}
                        style={{ left: i * PIXELS_PER_BEAT }}
                    >
                        {i % 4 === 0 && <span className="absolute top-0 left-1 text-[8px] text-slate-500 font-mono">{i}</span>}
                    </div>
                ))}

                {/* GHOST NOTES (From other tracks) */}
                {ghostTracks.map(track => 
                    track.muted ? null : track.notes.map(note => {
                        const top = (MIDI_MAX - note.midi) * NOTE_HEIGHT;
                        const left = note.startTime * PIXELS_PER_BEAT;
                        const width = note.duration * PIXELS_PER_BEAT;
                        return (
                            <div
                                key={`ghost-${track.id}-${note.id}`}
                                className="absolute rounded-sm bg-gray-500/20 border border-gray-500/30 pointer-events-none z-0"
                                style={{
                                    top: top + 1,
                                    left: left,
                                    width: Math.max(width - 1, 4),
                                    height: NOTE_HEIGHT - 2,
                                }}
                            />
                        )
                    })
                )}

                {/* ACTIVE NOTES */}
                {notes.map(note => {
                    const top = (MIDI_MAX - note.midi) * NOTE_HEIGHT;
                    const left = note.startTime * PIXELS_PER_BEAT;
                    const width = note.duration * PIXELS_PER_BEAT;
                    const isSelected = selectedNoteId === note.id;

                    // Generate Pitch Curve SVG Path
                    let pitchPath = '';
                    if (note.pitchPoints && note.pitchPoints.length > 0) {
                        const h = NOTE_HEIGHT - 2;
                        const w = Math.max(width - 1, 4);
                        const points = note.pitchPoints.map(p => {
                            const px = p.t * w;
                            const py = (h/2) - (p.v/24)*h; 
                            return `${px},${py}`;
                        });
                        pitchPath = `M ${points.join(' L ')}`;
                    }

                    return (
                        <div
                            key={note.id}
                            onMouseDown={(e) => handleNoteMouseDown(e, note, 'MOVE')}
                            className={`absolute rounded-sm border text-[10px] flex items-center pl-1 overflow-hidden shadow-sm group z-10
                                ${isSelected 
                                    ? 'bg-synth-pop border-white text-white shadow-lg ring-1 ring-white' 
                                    : 'bg-synth-accent/90 border-synth-accent text-synth-dark hover:bg-synth-accent'
                                }`}
                            style={{
                                top: top + 1,
                                left: left,
                                width: Math.max(width - 1, 4),
                                height: NOTE_HEIGHT - 2,
                                cursor: tool === 'POINTER' ? 'move' : 'default'
                            }}
                        >
                            {/* Pitch Curve Overlay */}
                            {pitchPath && (
                                <svg className="absolute inset-0 w-full h-full pointer-events-none opacity-50" viewBox={`0 0 ${Math.max(width-1,4)} ${NOTE_HEIGHT-2}`} preserveAspectRatio="none">
                                    <path d={pitchPath} stroke="white" strokeWidth="2" fill="none" />
                                </svg>
                            )}

                            <span className="truncate w-full pointer-events-none select-none relative z-10 drop-shadow-md">{note.lyric}</span>

                            {/* Resize Handle */}
                            {tool === 'POINTER' && (
                                <div 
                                    className={`absolute right-0 top-0 bottom-0 w-4 cursor-ew-resize z-20 flex items-center justify-center opacity-0 hover:opacity-100 ${isSelected ? 'opacity-100' : ''}`}
                                    onMouseDown={(e) => handleNoteMouseDown(e, note, 'RESIZE')}
                                >
                                    <div className="w-1 h-3 bg-white/60 rounded-full" />
                                </div>
                            )}
                        </div>
                    );
                })}

            </div>
        </div>
      </div>

       {/* Floating Action Controls */}
       {selectedNoteId && (
        <div className="absolute bottom-4 right-4 z-50 flex items-end gap-3 animate-in fade-in slide-in-from-bottom-4 duration-200 pointer-events-auto">
            {/* D-Pad */}
            <div className="bg-synth-panel/95 backdrop-blur border border-synth-grid rounded-2xl p-2 shadow-2xl flex flex-col items-center gap-1">
                <button onClick={() => moveSelectedNote(0, 1)} className="p-2 hover:bg-synth-accent/20 rounded-lg text-synth-accent transition-colors active:scale-95 bg-white/5"><ArrowUp size={20} /></button>
                <div className="flex gap-1">
                     <button onClick={() => moveSelectedNote(-0.25, 0)} className="p-2 hover:bg-synth-accent/20 rounded-lg text-synth-accent transition-colors active:scale-95 bg-white/5"><ArrowLeft size={20} /></button>
                     <button onClick={() => moveSelectedNote(0, -1)} className="p-2 hover:bg-synth-accent/20 rounded-lg text-synth-accent transition-colors active:scale-95 bg-white/5"><ArrowDown size={20} /></button>
                     <button onClick={() => moveSelectedNote(0.25, 0)} className="p-2 hover:bg-synth-accent/20 rounded-lg text-synth-accent transition-colors active:scale-95 bg-white/5"><ArrowRight size={20} /></button>
                </div>
            </div>
            <button onClick={() => deleteNote(selectedNoteId)} className="bg-red-500 hover:bg-red-600 text-white p-4 rounded-2xl shadow-xl active:scale-90 transition-all border border-red-400/50"><Trash2 size={24} /></button>
        </div>
      )}
    </div>
  );
};

import { SequencerNote, SequencerTrack, VocalPreset, VocalMode, VowelType } from '../types';

const TRACK_COLORS = [
    '#38bdf8', // Cyan
    '#f472b6', // Pink
    '#a78bfa', // Purple
    '#34d399', // Green
    '#fbbf24', // Amber
    '#f87171', // Red
    '#c084fc', // Violet
    '#22d3ee', // Light Blue
    '#a3e635', // Lime
    '#fb923c'  // Orange
];

/**
 * Parses RTTTL (Ring Tone Text Transfer Language) / RTX string
 */
function parseRtttl(text: string): { tracks: SequencerTrack[], bpm: number } {
  const parts = text.trim().split(':');
  if (parts.length < 3) throw new Error("Invalid RTTTL/RTX format");

  // Parse Defaults (e.g., d=4,o=5,b=63)
  const defaults = parts[1].toLowerCase().split(',').reduce((acc, curr) => {
     const [k, v] = curr.split('=');
     if (k && v) acc[k.trim()] = parseInt(v.trim());
     return acc;
  }, { d: 4, o: 5, b: 63 } as any);

  const notesStr = parts[2];
  const tokens = notesStr.split(',');

  const notes: SequencerNote[] = [];
  let currentTime = 0; // In Beats

  tokens.forEach(token => {
      let t = token.trim().toLowerCase();
      if (!t) return;

      // Parse Duration
      let durStr = '';
      while (t.length > 0 && /\d/.test(t[0])) {
          durStr += t[0];
          t = t.slice(1);
      }
      let durationVal = durStr ? parseInt(durStr) : defaults.d;

      // Calculate beats: 4 / durationVal (e.g. 4/4 = 1 beat, 4/8 = 0.5 beat)
      let beats = 4.0 / durationVal;

      // Parse Note
      let noteChar = t[0];
      t = t.slice(1);

      let sharp = false;
      if (t.length > 0 && t[0] === '#') {
          sharp = true;
          t = t.slice(1);
      }

      let dot = false;
      if (t.includes('.')) {
          dot = true;
          t = t.replace('.', '');
      }

      // Parse Octave
      let octave = defaults.o;
      if (t.length > 0 && /\d/.test(t)) {
          octave = parseInt(t);
      }

      if (dot) beats *= 1.5;

      if (noteChar === 'p') {
          // Rest
          currentTime += beats;
      } else {
          // Note Conversion
          const baseMap: any = { c:0, d:2, e:4, f:5, g:7, a:9, b:11 };
          let midi = (octave + 1) * 12 + baseMap[noteChar];
          if (sharp) midi++;

          notes.push({
              id: Math.random().toString(36).substr(2, 9),
              midi: midi,
              startTime: currentTime,
              duration: beats,
              lyric: 'la'
          });

          currentTime += beats;
      }
  });

  const track: SequencerTrack = {
      id: 'track-1',
      name: parts[0] || 'RTTTL Melody',
      color: TRACK_COLORS[0],
      notes: notes,
      volume: 0.8,
      muted: false,
      solo: false,
      vocalParams: {
        text: "la",
        preset: VocalPreset.MALE_BR,
        mode: VocalMode.SINGING,
        vowel: VowelType.A,
        jitter: 0.1,
        humanize: 0.1,
        breathiness: 0.2,
        formantShift: 1.0,
        speed: 1.0,
        pitch: 1.0,
        octaveShift: 0,
        glide: 0.1,
        wordGap: 0.05
      }
  };

  return { tracks: [track], bpm: defaults.b || 120 };
}

/**
 * Universal Parser (MIDI & RTTTL)
 */
export const parseMidiFile = (arrayBuffer: ArrayBuffer): { tracks: SequencerTrack[], bpm: number } => {
  const data = new DataView(arrayBuffer);

  // 1. Check for MIDI Header
  let isMidi = false;
  try {
      if (getText(data, 0, 4) === 'MThd') isMidi = true;
  } catch (e) {}

  // 2. Fallback to RTTTL if not MIDI
  if (!isMidi) {
      const decoder = new TextDecoder('utf-8');
      const text = decoder.decode(arrayBuffer);
      if (text.includes(':')) {
          return parseRtttl(text);
      }
      throw new Error("Unknown file format (Not MIDI or RTX/RTTTL)");
  }

  // 3. Parse MIDI
  let offset = 0;

  // Header Chunk
  const headerChunkType = getText(data, offset, 4);
  offset += 4;

  const headerLength = data.getUint32(offset);
  offset += 4;

  const format = data.getUint16(offset);
  offset += 2;
  const numTracks = data.getUint16(offset);
  offset += 2;
  const timeDivision = data.getUint16(offset); // Ticks per Quarter Note (PPQ)
  offset += 2;

  const tracks: SequencerTrack[] = [];
  let detectedBpm = 120;

  for (let t = 0; t < numTracks; t++) {
    if (offset >= data.byteLength) break;
    const trackChunkType = getText(data, offset, 4);
    offset += 4;

    if (trackChunkType !== 'MTrk') break;

    const trackLength = data.getUint32(offset);
    offset += 4;

    const trackEnd = offset + trackLength;
    let currentTimeTicks = 0;
    let runningStatus = 0;

    const activeNotes: Record<number, number> = {};
    const trackNotes: SequencerNote[] = [];
    let trackName = `Track ${t + 1}`;

    while (offset < trackEnd) {
      // Read Delta Time
      let deltaTime = 0;
      let byte = data.getUint8(offset++);
      deltaTime = byte & 0x7F;
      while (byte & 0x80) {
        byte = data.getUint8(offset++);
        deltaTime = (deltaTime << 7) | (byte & 0x7F);
      }

      currentTimeTicks += deltaTime;

      // Read Event Status
      let nextByte = data.getUint8(offset);
      let eventType = 0;

      if (nextByte & 0x80) {
        eventType = nextByte;
        offset++;
        if (eventType < 0xF0) runningStatus = eventType;
      } else {
        eventType = runningStatus;
      }

      // Process Event
      if (eventType === 0xFF) { 
        // Meta Event (FF <type> <len> <data>)
        const metaType = data.getUint8(offset++);
        const len = readVarLength();

        if (metaType === 0x51 && len === 3) {
            // Tempo Event: Microseconds per quarter note
            const microSeconds = (data.getUint8(offset) << 16) | (data.getUint8(offset + 1) << 8) | data.getUint8(offset + 2);
            detectedBpm = Math.round(60000000 / microSeconds);
        }
        else if (metaType === 0x03) {
            // Track Name
            trackName = getText(data, offset, len);
        }

        offset += len;
      } 
      else if (eventType === 0xF0 || eventType === 0xF7) {
        const len = readVarLength();
        offset += len;
      }
      else {
        // Voice Message
        const type = eventType & 0xF0;

        if (type === 0x80 || type === 0x90) { // Note Off / On
           const note = data.getUint8(offset++);
           const velocity = data.getUint8(offset++);

           if (type === 0x90 && velocity > 0) {
               // Note On
               activeNotes[note] = currentTimeTicks;
           } else {
               // Note Off
               if (activeNotes[note] !== undefined) {
                   const startTick = activeNotes[note];
                   const durationTicks = currentTimeTicks - startTick;
                   trackNotes.push({
                      id: Math.random().toString(36).substr(2, 9),
                      midi: note,
                      startTime: startTick / timeDivision,
                      duration: durationTicks / timeDivision,
                      lyric: "la"
                   });
                   delete activeNotes[note];
               }
           }
        } 
        else if (type === 0xC0 || type === 0xD0) {
           offset += 1; 
        } 
        else if (type === 0xB0 || type === 0xE0 || type === 0xA0) {
           offset += 2; 
        }
      }
    }

    if (trackNotes.length > 0) {
        tracks.push({
            id: `track-${t}-${Date.now()}`,
            name: trackName,
            color: TRACK_COLORS[tracks.length % TRACK_COLORS.length],
            notes: trackNotes.sort((a, b) => a.startTime - b.startTime),
            volume: 0.8,
            muted: false,
            solo: false,
            vocalParams: {
                text: "la",
                preset: VocalPreset.MALE_BR,
                mode: VocalMode.SINGING,
                vowel: VowelType.A,
                jitter: 0.1,
                humanize: 0.1,
                breathiness: 0.2,
                formantShift: 1.0,
                speed: 1.0,
                pitch: 1.0,
                octaveShift: 0,
                glide: 0.1,
                wordGap: 0.05
            }
        });
    }

    function readVarLength() {
        let len = 0;
        let b = data.getUint8(offset++);
        len = b & 0x7F;
        while (b & 0x80) {
            b = data.getUint8(offset++);
            len = (len << 7) | (b & 0x7F);
        }
        return len;
    }
  }

  return { tracks, bpm: detectedBpm };
};

function getText(data: DataView, offset: number, length: number) {
  let str = '';
  for (let i = 0; i < length; i++) {
    str += String.fromCharCode(data.getUint8(offset + i));
  }
  return str;
}

