// --- PLUGIN ENGINE ---

/**
 * Safe Math Expression Evaluator
 */
const evaluateMathExpression = (expr: string | number, scope: Record<string, number>): number => {
  if (typeof expr === 'number') return expr;
  if (!expr || typeof expr !== 'string') return 0;

  // If it's a simple variable reference
  if (scope[expr] !== undefined) return scope[expr];

  try {
    // Whitelist supported functions and variables
    const safeKeys = [...Object.keys(scope), 'Math'];
    const safeVals: any[] = [...Object.values(scope), Math];

    // Add custom helper functions
    const midiToFreq = (m: number) => 440 * Math.pow(2, (m - 69) / 12);
    safeKeys.push('midi_to_freq');
    safeVals.push(midiToFreq);

    // Create function
    const f = new Function(...safeKeys, `return ${expr};`);
    const res = f(...safeVals);
    return isNaN(res) ? 0 : res;
  } catch (e) {
    // console.warn(`Eval error for "${expr}":`, e);
    return 0;
  }
};

const makeDistortionCurve = (amount: number = 20) => {
  const k = typeof amount === 'number' ? amount : 20;
  const n_samples = 44100;
  const curve = new Float32Array(n_samples);
  const deg = Math.PI / 180;

  for (let i = 0; i < n_samples; ++i) {
    const x = (i * 2) / n_samples - 1;
    // Tanh-like curve
    curve[i] = (3 + k) * x * 20 * deg / (Math.PI + k * Math.abs(x));
  }
  return curve;
};

export const renderPlugin = async (ctx: OfflineAudioContext, plugin: PluginDefinition, params: Record<string, number>, duration: number, freq: number): Promise<AudioBuffer> => {

    // 1. Variable Scope
    const currentMidi = Math.round(69 + 12 * Math.log2(freq / 440));

    const scope: Record<string, number> = {
        ...params,
        midi_note: currentMidi,
        freq: freq,
        time: duration,
        pi: Math.PI
    };

    // 2. Create Nodes
    const nodeMap: Record<string, AudioNode> = {};
    const master = ctx.createGain();
    master.connect(ctx.destination);

    for (const nodeDef of plugin.nodes || []) {
        const nodeParams = nodeDef.params || {};

        // Evaluate all params for this node
        const evalParams: Record<string, number> = {};
        for (const [k, v] of Object.entries(nodeParams)) {
            evalParams[k] = evaluateMathExpression(v, scope);
        }

        let audioNode: AudioNode | null = null;

        // Normalize Function Names
        const func = nodeDef.function.toLowerCase();
        let normalizedFunc = func;
        if (func.includes('osc') || func.includes('wave')) {
             if (func.includes('sine')) normalizedFunc = 'sine_wave';
             if (func.includes('saw')) normalizedFunc = 'sawtooth_wave';
             if (func.includes('square')) normalizedFunc = 'square_wave';
             if (func.includes('triangle')) normalizedFunc = 'triangle_wave';
        }
        if (func.includes('filter')) normalizedFunc = 'filter';
        if (func === 'output' || func === 'output_node') normalizedFunc = 'output_node';
        if (func.includes('drive') || func.includes('dist')) normalizedFunc = 'distortion';

        // --- OSCILLATORS ---
        if (['sine_wave', 'sawtooth_wave', 'square_wave', 'triangle_wave'].includes(normalizedFunc)) {
            const osc = ctx.createOscillator();
            let type: OscillatorType = 'sine';
            if (normalizedFunc.includes('saw')) type = 'sawtooth';
            if (normalizedFunc.includes('square')) type = 'square';
            if (normalizedFunc.includes('triangle')) type = 'triangle';
            osc.type = type;

            const baseFrequency = evalParams.freq || freq;
            osc.frequency.setValueAtTime(baseFrequency, 0);

            // Vibrato Logic
            if (evalParams.vibrato_depth && evalParams.vibrato_rate) {
                const lfo = ctx.createOscillator();
                lfo.frequency.value = evalParams.vibrato_rate;
                const lfoGain = ctx.createGain();
                lfoGain.gain.value = baseFrequency * evalParams.vibrato_depth;
                lfo.connect(lfoGain);
                lfoGain.connect(osc.frequency);
                lfo.start(0);
            }

            const gain = ctx.createGain();
            const amp = evalParams.amplitude !== undefined ? evalParams.amplitude : 1.0;
            // Envelope (Start/Stop)
            gain.gain.setValueAtTime(amp, 0);
            gain.gain.setValueAtTime(amp, duration - 0.05);
            gain.gain.linearRampToValueAtTime(0, duration);

            osc.connect(gain);
            osc.start(0);
            osc.stop(duration);

            audioNode = gain;
        }
        // --- FILTER ---
        else if (normalizedFunc === 'filter') {
            const f = ctx.createBiquadFilter();
            // Try to deduce type from name if possible (e.g. lowpass_filter)
            if (nodeDef.function.includes('low')) f.type = 'lowpass';
            else if (nodeDef.function.includes('high')) f.type = 'highpass';
            else f.type = (nodeParams.type as BiquadFilterType) || 'lowpass';

            if (evalParams.frequency || evalParams.cutoff) f.frequency.value = evalParams.frequency || evalParams.cutoff || 2000;
            if (evalParams.Q || evalParams.resonance) f.Q.value = evalParams.Q || evalParams.resonance || 1;
            audioNode = f;
        }
        // --- GAIN ---
        else if (normalizedFunc === 'gain') {
            const g = ctx.createGain();
            g.gain.value = evalParams.gain !== undefined ? evalParams.gain : 1.0;
            audioNode = g;
        }
        // --- DISTORTION ---
        else if (normalizedFunc === 'distortion') {
            const shaper = ctx.createWaveShaper();
            const amount = evalParams.amount !== undefined ? evalParams.amount : 0.5; // 0 to 1 ideally, mapping to curve
            // Scale amount for better effect
            shaper.curve = makeDistortionCurve(amount * 100);
            shaper.oversample = '4x';
            audioNode = shaper;
        }
        // --- OUTPUT ---
        else if (normalizedFunc === 'output_node') {
            const g = ctx.createGain();
            g.gain.value = 1.0;
            g.connect(master);
            audioNode = g;
        }

        if (audioNode) {
            nodeMap[nodeDef.name] = audioNode;

            // Connect Inputs
            if (nodeDef.inputs && nodeDef.inputs.length > 0) {
                nodeDef.inputs.forEach(inputName => {
                    const sourceNode = nodeMap[inputName];
                    if (sourceNode) {
                        try {
                            sourceNode.connect(audioNode as AudioNode);
                        } catch(e) { /* ignore connection errors */ }
                    }
                });
            }
        }
    }

    return ctx.startRendering();
};


/**
 * Enhanced Vocal Synthesis with Text Sequencing
 */
export const renderVocals = async (ctx: OfflineAudioContext, params: VocalParams, duration: number, baseFreq: number, startFreq?: number): Promise<AudioBuffer> => {

  // PLUGIN HANDLER INTERCEPT
  if (params.preset === VocalPreset.PLUGIN && params.pluginId) {
      if (params.customData && (params.customData as any).plugin_meta) {
          const pluginDef = params.customData as unknown as PluginDefinition;
          const pluginParams = params.pluginState || {};

          // Merge defaults
          const finalParams: Record<string, number> = {};
          Object.entries(pluginDef.parameters).forEach(([key, val]) => {
              finalParams[key] = pluginParams[key] !== undefined ? pluginParams[key] : val.default;
          });

          return renderPlugin(ctx, pluginDef, finalParams, duration, baseFreq * params.pitch);
      }
  }

  // 1. Prepare Text & Phonemes via Parser
  const phonemes = textToPhonemes(params.text);

  // 2. Calculate Timing (Variable Duration based on Phoneme Type)
  let totalUnits = 0;
  const phonemeSequence = phonemes.map(p => {
    const def = PHONEME_LIB[p] || PHONEME_LIB['a'];
    totalUnits += def.durationScale;
    return { char: p, def };
  });

  // If no text, avoid division by zero
  if (totalUnits === 0) totalUnits = 1;

  const unitTime = duration / totalUnits;

  // 3. Load Preset Config & Frequency
  // CHECK FOR CUSTOM DATA
  let presetData = VOCAL_PRESETS_DATA[params.preset];
  if (params.preset === VocalPreset.CUSTOM && params.customData) {
      presetData = params.customData;
  }
  // Fallback
  if (!presetData) presetData = VOCAL_PRESETS_DATA[VocalPreset.MALE_BR];

  // Use user provided baseFreq instead of preset default baseFreq unless mode forces it
  // We apply the preset pitch multiplier if any, but base it on the Global Note.
  const f0 = baseFreq * params.pitch;

  // 4. Build Source Chain
  const master = ctx.createGain();
  master.connect(ctx.destination);

  // Main Oscillator
  const osc = ctx.createOscillator();
  // Handle special types
  let oscType = presetData.type;
  if (oscType === 'pulse') oscType = 'square'; // Map pulse to square for Web Audio (could use PWM but simplified)
  if (oscType === 'custom') oscType = 'sawtooth'; // Fallback
  osc.type = oscType as OscillatorType;

  // Pitch Logic (Speech vs Singing) & Automation
  if (startFreq && params.glide > 0) {
      // GLIDE / PORTAMENTO
      // Ramp from startFreq to f0
      osc.frequency.setValueAtTime(startFreq, 0);
      // Glide time is a fraction of note duration or fixed max
      // Map glide 0..1 to approx 0..0.5s max
      const glideTime = Math.min(duration, params.glide * 0.5); 
      // Use exponential ramp for natural slide
      osc.frequency.exponentialRampToValueAtTime(f0, glideTime);
  } else {
      osc.frequency.setValueAtTime(f0, 0);
  }

  // Apply Pitch Bend (Curve) via Detune (Works on top of frequency automation)
  if (params.pitchPoints && params.pitchPoints.length > 0) {
     const sorted = [...params.pitchPoints].sort((a,b) => a.t - b.t);
     if (sorted[0].t > 0) {
         osc.detune.setValueAtTime(0, 0);
     }
     sorted.forEach((pt, i) => {
          const t = pt.t * duration;
          const cents = pt.v * 100; 
          if (t === 0) {
            osc.detune.setValueAtTime(cents, 0);
          } else {
            osc.detune.linearRampToValueAtTime(cents, t);
          }
     });
  }

  // If Speech Mode (TTS), we apply a prosody curve
  // Standard prosody: Slight rise at start, gradual fall at end.
  // Variations on stressed syllables can be added in loop.
  if (params.mode === VocalMode.SPEECH) {
    const startPitch = f0 * 1.1;
    const endPitch = f0 * 0.85;
    osc.frequency.setValueAtTime(startPitch, 0);
    // Add small variations per phoneme in the loop, but general trend is falling
    osc.frequency.exponentialRampToValueAtTime(endPitch, duration);
  }

  // Preset Pitch Drop/Rise effects
  if (presetData.pitchDrop) {
      osc.frequency.setValueAtTime(f0, 0);
      osc.frequency.exponentialRampToValueAtTime(f0 * 0.8, duration);
  }
  if (presetData.pitchRise) {
      osc.frequency.setValueAtTime(f0, 0);
      osc.frequency.exponentialRampToValueAtTime(f0 * 1.2, duration);
  }

  // Pitch Modulations (Vibrato / Drift / FM / Flutter)
  if (presetData.vibrato && params.mode !== VocalMode.SPEECH) {
     const lfo = ctx.createOscillator();
     lfo.frequency.value = presetData.vibrato.rate;
     const lfoGain = ctx.createGain();
     // If pitch bending, vibrato applies on top
     lfoGain.gain.value = f0 * presetData.vibrato.depth;
     lfo.connect(lfoGain);
     lfoGain.connect(osc.frequency);
     lfo.start(0);
  }

  // HUMAN INSTABILITY (Slow Drift + Error)
  if (params.humanize > 0) {
    // We use a low freq oscillator to simulate "human error" in holding pitch
    const driftOsc = ctx.createOscillator();
    driftOsc.frequency.value = 0.5 + (Math.random() * 2); // Slow drift 0.5Hz - 2.5Hz
    const driftGain = ctx.createGain();
    // Drifts up to +/- semitone at max humanize
    driftGain.gain.value = f0 * 0.06 * params.humanize; 
    driftOsc.connect(driftGain);
    driftGain.connect(osc.frequency);
    driftOsc.start(0);
  }

  if (presetData.flutter) {
      const flutterOsc = ctx.createOscillator();
      flutterOsc.frequency.value = 0.3;
      const fGain = ctx.createGain();
      fGain.gain.value = 10;
      flutterOsc.connect(fGain);
      fGain.connect(osc.frequency);
      flutterOsc.start(0);
  }

  if (presetData.fm) {
      // FM Synthesis: Modulator Oscillator
      const fmOsc = ctx.createOscillator();
      // FM Rate: Can be absolute or relative (ratio). 
      // For simple bell implementation (prompt), let's assume `rate` is a multiplier if < 20, else absolute Hz.
      const fmRate = presetData.fm.rate; 
      const isRatio = fmRate < 50; 

      if (isRatio) {
          fmOsc.frequency.value = f0 * fmRate;
      } else {
          fmOsc.frequency.value = fmRate;
      }

      const fmGain = ctx.createGain();
      fmGain.gain.value = presetData.fm.depth;

      // Basic envelope for FM to make it percussive (bell-like)
      if (presetData.type === 'custom' || presetData.type === 'sine') {
           // Decay FM amount over time
           fmGain.gain.setValueAtTime(presetData.fm.depth, 0);
           fmGain.gain.exponentialRampToValueAtTime(0.01, duration);
      }

      fmOsc.connect(fmGain);
      fmGain.connect(osc.frequency);
      fmOsc.start(0);
  }

  // OSC GAIN (Controlled by Phoneme Envelope)
  const oscGainNode = ctx.createGain();
  // We will automate this gain
  oscGainNode.gain.setValueAtTime(0, 0); 
  osc.connect(oscGainNode);

  // NOISE SOURCE
  const noiseBuff = ctx.createBuffer(1, ctx.sampleRate * duration, ctx.sampleRate);
  const nd = noiseBuff.getChannelData(0);
  for(let i=0; i<nd.length; i++) nd[i] = (Math.random() * 2 - 1) * 0.5;
  const noiseSrc = ctx.createBufferSource();
  noiseSrc.buffer = noiseBuff;

  // Noise Shaping Filter (for fricatives like 's' vs 'sh')
  const noiseFilter = ctx.createBiquadFilter();
  noiseFilter.type = 'highpass';
  noiseFilter.frequency.value = 1000; // Default
  noiseSrc.connect(noiseFilter);

  const noiseGain = ctx.createGain();
  noiseGain.gain.setValueAtTime(0, 0);
  noiseFilter.connect(noiseGain);

  // Combine Sources
  const sourceSum = ctx.createGain();
  oscGainNode.connect(sourceSum);
  noiseGain.connect(sourceSum);

  // Sub-harmonics
  if (presetData.subHarmonics) {
      const subOsc = ctx.createOscillator();
      subOsc.type = 'square';
      subOsc.frequency.value = f0 / 2;
      const subGain = ctx.createGain();
      subGain.gain.value = 0.5;
      subOsc.connect(subGain);
      subGain.connect(sourceSum);
      subOsc.start(0);
  }

  // 5. Formant Filters (Parallel Bandpass)
  const filterOut = ctx.createGain();

  const filters = [0,1,2].map(i => {
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.Q.value = 4 + i; 
    const g = ctx.createGain();
    g.gain.value = 1.0; 
    sourceSum.connect(f);
    f.connect(g);
    g.connect(filterOut);
    return f;
  });

  // Nasal Branch
  let nasalOut: GainNode | null = null;
  const nasalF = ctx.createBiquadFilter();
  nasalF.type = 'bandpass';
  nasalF.frequency.value = 400;
  nasalF.Q.value = 3;
  nasalOut = ctx.createGain();
  nasalOut.gain.value = 0; // Controlled by sequence
  sourceSum.connect(nasalF);
  nasalF.connect(nasalOut);
  nasalOut.connect(master);

  // 6. Automation Sequencing
  // Word Gap Articulation Gain
  const articulationGain = ctx.createGain();
  articulationGain.gain.value = 1;
  filterOut.connect(articulationGain);

  let currentTime = 0;
  const rampMethod = presetData.steps ? 'setValueAtTime' : 'linearRampToValueAtTime'; // Linear for formants usually better for consonants

  phonemeSequence.forEach((item, idx) => {
    const { char, def } = item;
    const itemDur = def.durationScale * unitTime;
    const endTime = currentTime + itemDur;

    // Pitch automation for Speech Mode (Micro-prosody)
    if (params.mode === VocalMode.SPEECH) {
        // Vowels slightly higher/stable, consonants might drop
        // Random intonation drift based on Humanize
        const variance = (Math.random() * 2 - 1) * 0.1 * params.humanize;
    }

    // -- FORMANTS --
    let [t1, t2, t3] = def.formants;
    const scale = presetData.formantScale || 1.0;
    const shift = params.formantShift || 1.0;
    t1 *= scale * shift;
    t2 *= scale * shift;
    t3 *= scale * shift;

    // Clamp
    t1 = Math.max(50, Math.min(10000, t1));
    t2 = Math.max(50, Math.min(10000, t2));
    t3 = Math.max(50, Math.min(10000, t3));

    // Apply Formants
    if (idx === 0) {
        filters[0].frequency.setValueAtTime(t1, currentTime);
        filters[1].frequency.setValueAtTime(t2, currentTime);
        filters[2].frequency.setValueAtTime(t3, currentTime);
    } else {
        filters[0].frequency[rampMethod](t1, currentTime + (itemDur * 0.5));
        filters[1].frequency[rampMethod](t2, currentTime + (itemDur * 0.5));
        filters[2].frequency[rampMethod](t3, currentTime + (itemDur * 0.5));
    }

    // -- SOURCE MIXING (Osc vs Noise) --
    // Base Osc Level from preset
    const presetOscLevel = presetData.oscGain !== undefined ? presetData.oscGain : (1 - (presetData.breath || 0));
    // Def Osc Level (0 for consonants like p, t, k, s)
    const defOscLevel = def.gain; 
    const finalOscLevel = presetOscLevel * defOscLevel;

    oscGainNode.gain.setTargetAtTime(finalOscLevel, currentTime, 0.01);

    // Noise Level
    const presetBreath = (presetData.breath || 0) + params.breathiness * 0.2;
    // Def Noise Level (High for f, s, sh)
    const defNoiseLevel = def.noise;
    // Max of preset breath or consonant noise
    const finalNoiseLevel = Math.max(presetBreath, defNoiseLevel * 0.8);

    noiseGain.gain.setTargetAtTime(finalNoiseLevel, currentTime, 0.01);

    // Noise Color
    if (def.noiseType === 'highpass') {
        noiseFilter.frequency.setTargetAtTime(4000, currentTime, 0.01);
    } else if (def.noiseType === 'pink') {
        noiseFilter.frequency.setTargetAtTime(1000, currentTime, 0.01);
    } else {
        noiseFilter.frequency.setTargetAtTime(100, currentTime, 0.01); // White/Full
    }

    // -- NASAL MIX --
    const nasalTarget = (char.match(/[ãẽĩõũmnɲ]/)) ? (presetData.nasal || 0.4) : 0;
    nasalOut!.gain.setTargetAtTime(nasalTarget, currentTime, 0.05);

    // -- WORD GAP / PAUSE --
    if (char === ' ') {
        if (params.wordGap > 0) {
           articulationGain.gain.setTargetAtTime(0, currentTime, 0.005);
        }
    } else {
        if (params.wordGap > 0) {
           articulationGain.gain.setTargetAtTime(1, currentTime, 0.01);
        }
    }

    currentTime = endTime;
  });

  // 7. Post-Filter Effects
  let postFx = articulationGain; 
  if (presetData.amRate) {
      const am = ctx.createGain();
      const lfo = ctx.createOscillator();
      lfo.frequency.value = presetData.amRate;
      const lfoG = ctx.createGain();
      lfoG.gain.value = presetData.amDepth || 0.5;
      const offset = ctx.createConstantSource();
      offset.offset.value = 1;

      lfo.connect(lfoG);
      lfoG.connect(am.gain);
      offset.connect(am.gain);

      articulationGain.disconnect();
      articulationGain.connect(am);
      postFx = am;

      lfo.start(0);
      offset.start(0);
  }

  // Compressor (simple limiter via DynamicsCompressor)
  if (presetData.comp) {
      const comp = ctx.createDynamicsCompressor();
      comp.threshold.value = -24;
      comp.knee.value = 30;
      comp.ratio.value = 12;
      comp.attack.value = 0.003;
      comp.release.value = 0.25;
      postFx.connect(comp);
      postFx = comp as unknown as GainNode;
  }

  if (presetData.bandpass) {
      const bpLow = ctx.createBiquadFilter();
      bpLow.type = 'highpass';
      bpLow.frequency.value = presetData.bandpass[0];
      const bpHigh = ctx.createBiquadFilter();
      bpHigh.type = 'lowpass';
      bpHigh.frequency.value = presetData.bandpass[1];

      postFx.connect(bpLow);
      bpLow.connect(bpHigh);
      postFx = bpHigh as unknown as GainNode; 
  }

  postFx.connect(master);

  osc.start(0);
  noiseSrc.start(0);
  osc.stop(duration);
  noiseSrc.stop(duration);

  const rendered = await ctx.startRendering();

  // 8. Buffer Post-Process
  const data = rendered.getChannelData(0);
  const len = data.length;

  if (presetData.roughness || params.jitter > 0) {
      const rAmount = (presetData.roughness || 0) + params.jitter;
      for(let i=0; i<len; i++) {
          data[i] *= 1 + ((Math.random() - 0.5) * rAmount);
      }
  }

  if (presetData.distortion) {
      const k = presetData.distortion;
      for(let i=0; i<len; i++) {
          data[i] = Math.tanh(k * data[i]);
      }
  } else if (presetData.clip) {
      const limit = presetData.clip;
      for(let i=0; i<len; i++) {
          if (data[i] > limit) data[i] = limit;
          if (data[i] < -limit) data[i] = -limit;
      }
  } else {
      for(let i=0; i<len; i++) data[i] = Math.tanh(data[i]);
  }

  return rendered;
};


/**
 * Render Project Logic
 */
export const renderProject = async (mainCtx: OfflineAudioContext, tracks: SequencerTrack[], bpm: number, sampleRate: number): Promise<AudioBuffer> => {
     const secondsPerBeat = 60 / bpm;

     // Collect all note render promises
     const renderPromises: Promise<{ buffer: AudioBuffer, startTime: number, trackVolume: number, trackMuted: boolean }>[] = [];

     for (const track of tracks) {
         if (track.muted) continue;

         const sortedNotes = [...track.notes].sort((a,b) => a.startTime - b.startTime);

         for (let i=0; i < sortedNotes.length; i++) {
             const note = sortedNotes[i];
             // const nextNote = sortedNotes[i+1];

             const startTime = note.startTime * secondsPerBeat;
             const duration = note.duration * secondsPerBeat;

             // Prepare Params
             const params = { ...track.vocalParams, text: note.lyric };
             if (note.pitchPoints) params.pitchPoints = note.pitchPoints;

             // WE MUST PASS THE FULL PLUGIN DEFINITION IF PRESENT
             // Hack: we store the plugin definition in customData for the renderer
             if (track.vocalParams.preset === VocalPreset.PLUGIN) {
                  // We need to fetch the plugin definition from the App State (via a global or context). 
                  // Since renderProject is outside React state, we assume `track.vocalParams.customData` 
                  // MIGHT contain the definition if we set it up right in App.tsx.
             }

             // Calculate Frequencies
             const freq = midiToFreq(note.midi);

             let startFreq = freq;
             if (params.glide > 0 && i > 0) {
                 const prev = sortedNotes[i-1];
                 // If previous note ends close to this one (within small threshold), glide from it
                 if (note.startTime - (prev.startTime + prev.duration) < 0.25) {
                     startFreq = midiToFreq(prev.midi);
                 }
             }

             // Create isolated context for this note
             const noteCtx = new OfflineAudioContext(1, Math.ceil(sampleRate * duration) + 1000, sampleRate);

             renderPromises.push(
                renderVocals(noteCtx, params, duration, freq, startFreq).then(buffer => ({
                    buffer,
                    startTime,
                    trackVolume: track.volume,
                    trackMuted: track.muted
                }))
             );
         }
     }

     const renderedNotes = await Promise.all(renderPromises);

     // Compose on Main Context
     renderedNotes.forEach(item => {
         const source = mainCtx.createBufferSource();
         source.buffer = item.buffer;
         const gain = mainCtx.createGain();
         gain.gain.value = item.trackVolume;
         source.connect(gain);
         gain.connect(mainCtx.destination);
         source.start(item.startTime);
     });

     return mainCtx.startRendering();
}

