  // Sampler Helpers
  const updateSamplerConfig = (updates: Partial<SamplerConfig>) => {
      updateActiveTrackParams(prev => {
          const currentData = prev.customData || { ...VOCAL_PRESETS_DATA[VocalPreset.SAMPLER] };
          const currentSampler = currentData.sampler || {
