import { SequencerNote, SequencerTrack, VocalPreset, VocalMode, VowelType, VocalLanguage } from '../types';

const TRACK_COLORS = [
    '#38bdf8', // Cyan
    '#f472b6', // Pink
    '#a78bfa', // Purple
    '#34d399', // Green
    '#fbbf24', // Amber
    '#f87171', // Red
    '#c084fc', // Violet
    '#22d3ee', // Light Blue
    '#a3e635', // Lime
    '#fb923c'  // Orange
];

/**
 * Parses RTTTL (Ring Tone Text Transfer Language) / RTX string
 */
function parseRtttl(text: string): { tracks: SequencerTrack[], bpm: number } {
  const parts = text.trim().split(':');
  if (parts.length < 3) throw new Error("Invalid RTTTL/RTX format");

  // Parse Defaults (e.g., d=4,o=5,b=63)
  const defaults = parts[1].toLowerCase().split(',').reduce((acc, curr) => {
     const [k, v] = curr.split('=');
     if (k && v) acc[k.trim()] = parseInt(v.trim());
     return acc;
  }, { d: 4, o: 5, b: 63 } as any);

  const notesStr = parts[2];
  const tokens = notesStr.split(',');

  const notes: SequencerNote[] = [];
  let currentTime = 0; // In Beats

  tokens.forEach(token => {
      let t = token.trim().toLowerCase();
      if (!t) return;

      // Parse Duration
      let durStr = '';
      while (t.length > 0 && /\d/.test(t[0])) {
          durStr += t[0];
          t = t.slice(1);
      }
      let durationVal = durStr ? parseInt(durStr) : defaults.d;

      // Calculate beats: 4 / durationVal (e.g. 4/4 = 1 beat, 4/8 = 0.5 beat)
      let beats = 4.0 / durationVal;

      // Parse Note
      let noteChar = t[0];
      t = t.slice(1);

      let sharp = false;
      if (t.length > 0 && t[0] === '#') {
          sharp = true;
          t = t.slice(1);
      }

      let dot = false;
      if (t.includes('.')) {
          dot = true;
          t = t.replace('.', '');
      }

      // Parse Octave
      let octave = defaults.o;
      if (t.length > 0 && /\d/.test(t)) {
          octave = parseInt(t);
      }

      if (dot) beats *= 1.5;

      if (noteChar === 'p') {
          // Rest
          currentTime += beats;
      } else {
          // Note Conversion
          const baseMap: any = { c:0, d:2, e:4, f:5, g:7, a:9, b:11 };
          let midi = (octave + 1) * 12 + baseMap[noteChar];
          if (sharp) midi++;

          notes.push({
              id: Math.random().toString(36).substr(2, 9),
              midi: midi,
              startTime: currentTime,
              duration: beats,
              lyric: 'la'
          });

          currentTime += beats;
      }
  });

  const track: SequencerTrack = {
      id: 'track-1',
      name: parts[0] || 'RTTTL Melody',
      color: TRACK_COLORS[0],
      notes: notes,
      volume: 0.8,
      muted: false,
      solo: false,
      vocalParams: {
        text: "la",
        preset: VocalPreset.MALE_BR,
        language: VocalLanguage.PT_BR,
        mode: VocalMode.SINGING,
        vowel: VowelType.A,
        jitter: 0.1,
        humanize: 0.1,
        breathiness: 0.2,
        formantShift: 1.0,
        speed: 1.0,
        pitch: 1.0,
        octaveShift: 0,
        glide: 0.1,
        wordGap: 0.05
      }
  };

  return { tracks: [track], bpm: defaults.b || 120 };
}

/**
 * Universal Parser (MIDI & RTTTL)
 */
export const parseMidiFile = (arrayBuffer: ArrayBuffer): { tracks: SequencerTrack[], bpm: number } => {
  const data = new DataView(arrayBuffer);

  // 1. Check for MIDI Header
  let isMidi = false;
  try {
      if (getText(data, 0, 4) === 'MThd') isMidi = true;
  } catch (e) {}

  // 2. Fallback to RTTTL if not MIDI
  if (!isMidi) {
      const decoder = new TextDecoder('utf-8');
      const text = decoder.decode(arrayBuffer);
      if (text.includes(':')) {
          return parseRtttl(text);
      }
      throw new Error("Unknown file format (Not MIDI or RTX/RTTTL)");
  }

  // 3. Parse MIDI
  let offset = 0;

  // Header Chunk
  const headerChunkType = getText(data, offset, 4);
  offset += 4;

  const headerLength = data.getUint32(offset);
  offset += 4;

  const format = data.getUint16(offset);
  offset += 2;
  const numTracks = data.getUint16(offset);
  offset += 2;
  const timeDivision = data.getUint16(offset); // Ticks per Quarter Note (PPQ)
  offset += 2;

  const tracks: SequencerTrack[] = [];
  let detectedBpm = 120;

  for (let t = 0; t < numTracks; t++) {
    if (offset >= data.byteLength) break;
    const trackChunkType = getText(data, offset, 4);
    offset += 4;

    if (trackChunkType !== 'MTrk') break;

    const trackLength = data.getUint32(offset);
    offset += 4;

    const trackEnd = offset + trackLength;
    let currentTimeTicks = 0;
    let runningStatus = 0;

    const activeNotes: Record<number, number> = {};
    const trackNotes: SequencerNote[] = [];
    let trackName = `Track ${t + 1}`;

    while (offset < trackEnd) {
      // Read Delta Time
      let deltaTime = 0;
      let byte = data.getUint8(offset++);
      deltaTime = byte & 0x7F;
      while (byte & 0x80) {
        byte = data.getUint8(offset++);
        deltaTime = (deltaTime << 7) | (byte & 0x7F);
      }

      currentTimeTicks += deltaTime;

      // Read Event Status
      let nextByte = data.getUint8(offset);
      let eventType = 0;

      if (nextByte & 0x80) {
        eventType = nextByte;
        offset++;
        if (eventType < 0xF0) runningStatus = eventType;
      } else {
        eventType = runningStatus;
      }

      // Process Event
      if (eventType === 0xFF) { 
        // Meta Event (FF <type> <len> <data>)
        const metaType = data.getUint8(offset++);
        const len = readVarLength();

        if (metaType === 0x51 && len === 3) {
            // Tempo Event: Microseconds per quarter note
            const microSeconds = (data.getUint8(offset) << 16) | (data.getUint8(offset + 1) << 8) | data.getUint8(offset + 2);
            detectedBpm = Math.round(60000000 / microSeconds);
        }
        else if (metaType === 0x03) {
            // Track Name
            trackName = getText(data, offset, len);
        }

        offset += len;
      } 
      else if (eventType === 0xF0 || eventType === 0xF7) {
        const len = readVarLength();
        offset += len;
      }
      else {
        // Voice Message
        const type = eventType & 0xF0;

        if (type === 0x80 || type === 0x90) { // Note Off / On
           const note = data.getUint8(offset++);
           const velocity = data.getUint8(offset++);

           if (type === 0x90 && velocity > 0) {
               // Note On
               activeNotes[note] = currentTimeTicks;
           } else {
               // Note Off
               if (activeNotes[note] !== undefined) {
                   const startTick = activeNotes[note];
                   const durationTicks = currentTimeTicks - startTick;
                   trackNotes.push({
                      id: Math.random().toString(36).substr(2, 9),
                      midi: note,
                      startTime: startTick / timeDivision,
                      duration: durationTicks / timeDivision,
                      lyric: "la"
                   });
                   delete activeNotes[note];
               }
           }
        } 
        else if (type === 0xC0 || type === 0xD0) {
           offset += 1; 
        } 
        else if (type === 0xB0 || type === 0xE0 || type === 0xA0) {
           offset += 2; 
        }
      }
    }

    if (trackNotes.length > 0) {
        tracks.push({
            id: `track-${t}-${Date.now()}`,
            name: trackName,
            color: TRACK_COLORS[tracks.length % TRACK_COLORS.length],
            notes: trackNotes.sort((a, b) => a.startTime - b.startTime),
            volume: 0.8,
            muted: false,
            solo: false,
            vocalParams: {
                text: "la",
                preset: VocalPreset.MALE_BR,
                language: VocalLanguage.PT_BR,
                mode: VocalMode.SINGING,
                vowel: VowelType.A,
                jitter: 0.1,
                humanize: 0.1,
                breathiness: 0.2,
                formantShift: 1.0,
                speed: 1.0,
                pitch: 1.0,
                octaveShift: 0,
                glide: 0.1,
                wordGap: 0.05
            }
        });
    }

    function readVarLength() {
        let len = 0;
        let b = data.getUint8(offset++);
        len = b & 0x7F;
        while (b & 0x80) {
            b = data.getUint8(offset++);
            len = (len << 7) | (b & 0x7F);
        }
        return len;
    }
  }

  return { tracks, bpm: detectedBpm };
};

function getText(data: DataView, offset: number, length: number) {
  let str = '';
  for (let i = 0; i < length; i++) {
    str += String.fromCharCode(data.getUint8(offset + i));
  }
  return str;
}

import { 
  VocalPreset, VocalMode, VocalParams, SequencerNote, SequencerTrack, AudioPresetDefinition, PluginDefinition, SamplerConfig, VocalLanguage
} from '../types';

declare const lamejs: any;

// Constants
export const NOTE_FREQUENCIES: Record<string, number> = {
  'C': 16.35, 'C#': 17.32, 'D': 18.35, 'D#': 19.45, 'E': 20.60, 'F': 21.83,
  'F#': 23.12, 'G': 24.50, 'G#': 25.96, 'A': 27.50, 'A#': 29.14, 'B': 30.87
};

export const getFrequency = (note: string, octave: number): number => {
  const base = NOTE_FREQUENCIES[note] || 16.35;
  return base * Math.pow(2, octave);
};

export const midiToFreq = (midi: number): number => {
  return 440 * Math.pow(2, (midi - 69) / 12);
};

// --- AUDIO UTILS ---

export const decodeAudioData = async (ctx: AudioContext | OfflineAudioContext, base64: string): Promise<AudioBuffer> => {
    const binaryString = window.atob(base64.split(',')[1]);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return await ctx.decodeAudioData(bytes.buffer);
};

// Auto-Slicer based on Amplitude Threshold
export const detectSlices = (buffer: AudioBuffer, sensitivity: number): {start: number, end: number}[] => {
    const data = buffer.getChannelData(0);
    const step = Math.floor(buffer.sampleRate / 100); // 10ms resolution
    const slices = [];
    const threshold = 0.01 + ((1 - sensitivity) * 0.1); // Sensitivity maps 0..1 to threshold

    let isSilent = true;
    let startSample = 0;

    for(let i=0; i<data.length; i+=step) {
        // RMS of chunk
        let sum = 0;
        for(let j=0; j<step && i+j<data.length; j++) {
            sum += data[i+j] * data[i+j];
        }
        const rms = Math.sqrt(sum / step);

        if (isSilent && rms > threshold) {
            isSilent = false;
            startSample = i;
        } else if (!isSilent && rms < threshold) {
            isSilent = true;
            // End of slice
            if (i - startSample > step * 5) { // Min duration
                slices.push({
                    start: startSample / data.length,
                    end: i / data.length
                });
            }
        }
    }

    // Add final if not silent
    if (!isSilent) {
        slices.push({
            start: startSample / data.length,
            end: 1.0
        });
    }

    // If no slices detected, return full buffer
    if (slices.length === 0) return [{start: 0, end: 1}];

    return slices;
};

// --- ENCODING UTILS ---

export const bufferToMp3 = (buffer: AudioBuffer, bitrate: number): Blob => {
    if (typeof lamejs === 'undefined') {
        throw new Error("LameJS not found. Cannot encode MP3.");
    }

    const channels = buffer.numberOfChannels;
    const sampleRate = buffer.sampleRate;
    const mp3enc = new lamejs.Mp3Encoder(channels, sampleRate, bitrate);
    const left = buffer.getChannelData(0);
    const right = channels > 1 ? buffer.getChannelData(1) : left;

    // Convert float to int16 for LAME
    const sampleBlockSize = 1152;
    const mp3Data = [];

    // LAME expects Int16
    const l16 = new Int16Array(left.length);
    const r16 = new Int16Array(right.length);
    for(let i=0; i<left.length; i++) {
        l16[i] = Math.max(-1, Math.min(1, left[i])) * 32767;
        r16[i] = Math.max(-1, Math.min(1, right[i])) * 32767;
    }

    for (let i = 0; i < l16.length; i += sampleBlockSize) {
        const leftChunk = l16.subarray(i, i + sampleBlockSize);
        const rightChunk = r16.subarray(i, i + sampleBlockSize);
        let mp3buf;
        if (channels === 1) {
            mp3buf = mp3enc.encodeBuffer(leftChunk);
        } else {
            mp3buf = mp3enc.encodeBuffer(leftChunk, rightChunk);
        }
        if (mp3buf.length > 0) mp3Data.push(mp3buf);
    }

    const endBuf = mp3enc.flush();
    if (endBuf.length > 0) mp3Data.push(endBuf);

    return new Blob(mp3Data, { type: 'audio/mp3' });
};

// Helper: Convert AudioBuffer to WAV Blob with configurable Bit Depth
export const bufferToWav = (buffer: AudioBuffer, bitDepth: 8 | 16 | 32 = 16): Blob => {
  const numOfChan = buffer.numberOfChannels;
  const sampleRate = buffer.sampleRate;

  // 32-bit Float requires different format code (3) than PCM (1)
  const format = bitDepth === 32 ? 3 : 1; 

  // Calculate Size
  const bytesPerSample = bitDepth / 8;
  const blockAlign = numOfChan * bytesPerSample;
  const length = buffer.length * blockAlign + 44;

  const bufferArr = new ArrayBuffer(length);
  const view = new DataView(bufferArr);
  const channels = [];
  let i;
  let offset = 0;
  let pos = 0;

  // write RIFF chunk descriptor
  setUint32(0x46464952); // "RIFF"
  setUint32(length - 8); // file length - 8
  setUint32(0x45564157); // "WAVE"

  // write fmt sub-chunk
  setUint32(0x20746d66); // "fmt "
  setUint32(16); // length = 16
  setUint16(format); // 1 = PCM, 3 = IEEE Float
  setUint16(numOfChan);
  setUint32(sampleRate);
  setUint32(sampleRate * blockAlign); // avg. bytes/sec
  setUint16(blockAlign); // block-align
  setUint16(bitDepth); // bits per sample

  // write data sub-chunk
  setUint32(0x61746164); // "data"
  setUint32(length - pos - 4); // chunk length

  // Get channel data
  for (i = 0; i < buffer.numberOfChannels; i++)
    channels.push(buffer.getChannelData(i));

  // Write Interleaved Data
  let sample;
  while (pos < length) { // Check length instead of buffer.length loop to handle bytes correct
    // We iterate samples based on buffer length actually
    if (offset >= buffer.length) break;

    for (i = 0; i < numOfChan; i++) {
       // Get float sample -1 to 1
       sample = Math.max(-1, Math.min(1, channels[i][offset]));

       if (bitDepth === 8) {
           // 8-bit is unsigned 0..255, 128 is silence
           // scale to 0..255
           sample = ((sample * 0.5 + 0.5) * 255);
           view.setUint8(pos, sample);
           pos += 1;
       } 
       else if (bitDepth === 16) {
           // 16-bit is signed -32768..32767
           sample = (sample < 0 ? sample * 32768 : sample * 32767) | 0;
           view.setInt16(pos, sample, true);
           pos += 2;
       } 
       else if (bitDepth === 32) {
           // 32-bit Float
           view.setFloat32(pos, sample, true);
           pos += 4;
       }
    }
    offset++;
  }

  function setUint16(data: number) {
    view.setUint16(pos, data, true);
    pos += 2;
  }

  function setUint32(data: number) {
    view.setUint32(pos, data, true);
    pos += 4;
  }

  return new Blob([bufferArr], { type: 'audio/wav' });
};

/**
 * Convolution Reverb Generator (Space/Resonance Model)
 */
export const applyReverb = async (ctx: OfflineAudioContext, inputBuffer: AudioBuffer, mix: number, decayTime: number): Promise<AudioBuffer> => {
  if (mix <= 0) return inputBuffer;

  const sampleRate = ctx.sampleRate;
  const length = inputBuffer.length;

  // 1. Generate Impulse Response (Exponential Decay Noise)
  // Model: y(t) = Noise(t) * e^(-t / T)
  const irLength = sampleRate * decayTime;
  const irBuffer = ctx.createBuffer(1, irLength, sampleRate);
  const irData = irBuffer.getChannelData(0);

  for (let i = 0; i < irLength; i++) {
    // White noise * exponential decay
    irData[i] = (Math.random() * 2 - 1) * Math.pow(1 - (i / irLength), 4);
  }

  // 2. Convolve
  const convCtx = new OfflineAudioContext(1, length, sampleRate);
  const source = convCtx.createBufferSource();
  source.buffer = inputBuffer;

  const convolver = convCtx.createConvolver();
  convolver.buffer = irBuffer;
  convolver.normalize = true;

  const dryGain = convCtx.createGain();
  const wetGain = convCtx.createGain();

  dryGain.gain.value = 1 - (mix * 0.5);
  wetGain.gain.value = mix;

  source.connect(dryGain);
  dryGain.connect(convCtx.destination);

  source.connect(convolver);
  convolver.connect(wetGain);
  wetGain.connect(convCtx.destination);

  source.start();
  return await convCtx.startRendering();
};

