  'マ': ['m','a'], 'ミ': ['m','i'], 'ム': ['m','u'], 'メ': ['m','e'], 'モ': ['m','o'],
  'ヤ': ['y','a'], 'ユ': ['y','u'], 'ヨ': ['y','o'],
  'ラ': ['r','a'], 'リ': ['r','i'], 'ル': ['r','u'], 'レ': ['r','e'], 'ロ': ['r','o'],
  'ワ': ['w','a'], 'ヲ': ['o'], 'ン': ['n'],
  'ガ': ['g','a'], 'ギ': ['g','i'], 'グ': ['g','u'], 'ゲ': ['g','e'], 'ゴ': ['g','o'],
  'ザ': ['z','a'], 'ジ': ['JH','i'], 'ズ': ['z','u'], 'ゼ': ['z','e'], 'ゾ': ['z','o'],
  'ダ': ['d','a'], 'ヂ': ['JH','i'], 'ヅ': ['z','u'], 'デ': ['d','e'], 'ド': ['d','o'],
  'バ': ['b','a'], 'ビ': ['b','i'], 'ブ': ['b','u'], 'ベ': ['b','e'], 'ボ': ['b','o'],
  'パ': ['p','a'], 'ピ': ['p','i'], 'プ': ['p','u'], 'ペ': ['p','e'], 'ポ': ['p','o'],
};

// --- LANGUAGE PARSERS ---

// 1. PORTUGUESE (NATIVE)
const parsePortuguese = (text: string): string[] => {
  let s = text.toLowerCase();
  s = s.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, "");
  s = s.replace(/nh/g, 'ɲ');
  s = s.replace(/lh/g, 'ʎ');
  s = s.replace(/ch/g, 'ʃ');
  s = s.replace(/rr/g, 'ʁ');
  s = s.replace(/ss/g, 's'); 
  s = s.replace(/c(?=[eiéí])/g, 's');
  s = s.replace(/c/g, 'k');
  s = s.replace(/qu(?=[eiéí])/g, 'k');
  s = s.replace(/q/g, 'k');
  s = s.replace(/g(?=[eiéí])/g, 'ʒ');
  s = s.replace(/gu(?=[eiéí])/g, 'g'); 
  s = s.replace(/([aeiouáéíóúãẽĩõũ])s([aeiouáéíóúãẽĩõũ])/g, '$1z$2');
  s = s.replace(/am\b/g, 'ã');
  s = s.replace(/em\b/g, 'ẽ');
  s = s.replace(/im\b/g, 'ĩ');
  s = s.replace(/om\b/g, 'õ');
  s = s.replace(/um\b/g, 'ũ');
  s = s.replace(/an\b/g, 'ã');
  s = s.replace(/en\b/g, 'ẽ');
  s = s.replace(/in\b/g, 'ĩ');
  s = s.replace(/on\b/g, 'õ');
  s = s.replace(/un\b/g, 'ũ');
  s = s.replace(/^r/, 'ʁ'); 
  s = s.replace(/r\b/g, 'ɾ'); 
  s = s.replace(/r/g, 'ɾ'); 

  const tokens = s.split('');
  const output: string[] = [];
  for (const char of tokens) {
    if (PHONEME_LIB[char]) {
      output.push(char);
    } else {
      // Fallback Vowels
      if (char === 'á' || char === 'à' || char === 'â') output.push('a');
      else if (char === 'é' || char === 'ê') output.push('e'); 
      else if (char === 'í') output.push('i');
      else if (char === 'ó' || char === 'ô') output.push('o'); 
      else if (char === 'ú') output.push('u');
      else if (char === 'ç') output.push('s');
      else if (char === 'j') output.push('ʒ');
      else if (char === 'x') output.push('ʃ'); 
      else if (char === 'h') { }
      else if (char === ' ') output.push(' ');
    }
  }
  return output;
};

// 2. ENGLISH (US) - Rule based approximation
const parseEnglish = (text: string): string[] => {
  let s = text.toLowerCase();
  s = s.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, ""); // Clean punctuation

  // Digraphs & Rules
  s = s.replace(/th/g, 'TH'); // Generic TH (Context hard to detect without dictionary)
  s = s.replace(/sh/g, 'SH');
  s = s.replace(/ch/g, 'CH');
  s = s.replace(/ph/g, 'F');
  s = s.replace(/ng/g, 'NG');
  s = s.replace(/wh/g, 'W');
  s = s.replace(/ck/g, 'K');
  s = s.replace(/qu/g, 'K W');
  s = s.replace(/tion/g, 'SH AH N');
  s = s.replace(/sion/g, 'ZH AH N');
  s = s.replace(/ee/g, 'IY');
  s = s.replace(/oo/g, 'UW');

  const output: string[] = [];
  const words = s.split(' ');

  for (const word of words) {
      if (!word) continue;

      // If the word is already tokenized by replacements (contains spaces or uppercase), split it
      // Simple loop over chars for now
      let i = 0;
      while (i < word.length) {
          // Check for Uppercase 2-char tokens (TH, SH, etc)
          if (i+1 < word.length && /[A-Z]/.test(word[i]) && /[A-Z]/.test(word[i+1])) {
              output.push(word.substring(i, i+2));
              i += 2;
              continue;
          }

          // Single Char Processing
          const c = word[i];

          // Basic Vowels to ARPAbet
          if (c === 'a') output.push('AE'); // Default 'cat'
          else if (c === 'e') output.push('EH'); // Default 'bed'
          else if (c === 'i') output.push('IH'); // Default 'sit'
          else if (c === 'o') output.push('AA'); // Default 'hot'
          else if (c === 'u') output.push('AH'); // Default 'cut'
          else if (c === 'y') output.push('IY'); // Default 'happy'

          // Consonants
          else if (c === 'b') output.push('B');
          else if (c === 'd') output.push('D');
          else if (c === 'f') output.push('F');
          else if (c === 'g') output.push('G');
          else if (c === 'h') output.push('HH');
          else if (c === 'j') output.push('JH');
          else if (c === 'k') output.push('K');
          else if (c === 'l') output.push('L');
          else if (c === 'm') output.push('M');
          else if (c === 'n') output.push('N');
          else if (c === 'p') output.push('P');
          else if (c === 'r') output.push('R');
          else if (c === 's') output.push('S');
          else if (c === 't') output.push('T');
          else if (c === 'v') output.push('V');
          else if (c === 'w') output.push('W');
          else if (c === 'z') output.push('Z');
          else if (c === 'x') { output.push('K'); output.push('S'); }

          // Handle existing codes from replace
          else if (PHONEME_LIB[c]) output.push(c); // Unlikely given lowercase, but logical

          i++;
      }
      output.push(' ');
  }

  return output;
};

// 3. JAPANESE (Romaji + Kana)
const parseJapanese = (text: string): string[] => {
    let s = text; // Keep case for Kanji checks if implemented later, but Kana is uniform
    const output: string[] = [];

    let i = 0;
    while (i < s.length) {
        let char = s[i];

        // 1. Check Kana Map (Lookahead for 2 chars, e.g., 'きゅ')
        let parsed = false;
        if (i + 1 < s.length) {
            const twoChars = s.substring(i, i+2);
            if (KANA_MAP[twoChars]) {
                output.push(...KANA_MAP[twoChars]);
                i += 2;
                parsed = true;
            }
        }

        if (!parsed) {
            // Single char check
            if (KANA_MAP[char]) {
                output.push(...KANA_MAP[char]);
                i++;
                parsed = true;
            }
        }

        // 2. If not Kana, treat as Romaji or Skip
        if (!parsed) {
            // Simple Romaji parser fallback
            const lower = char.toLowerCase();
            // Map simple romaji to phonemes
            if (lower === 'a') output.push('a');
            else if (lower === 'i') output.push('i');
            else if (lower === 'u') output.push('u');
            else if (lower === 'e') output.push('e');
            else if (lower === 'o') output.push('o');
            // Common Consonants
            else if (lower === 'k') output.push('k');
            else if (lower === 's') output.push('s');
            else if (lower === 't') output.push('t');
            else if (lower === 'n') output.push('n');
            else if (lower === 'h') output.push('h');
            else if (lower === 'm') output.push('m');
            else if (lower === 'y') output.push('y');
            else if (lower === 'r') output.push('r');
            else if (lower === 'w') output.push('w');
            else if (lower === 'g') output.push('g');
            else if (lower === 'z') output.push('z');
            else if (lower === 'd') output.push('d');
            else if (lower === 'b') output.push('b');
            else if (lower === 'p') output.push('p');
            else if (lower === ' ') output.push(' ');
            else if (PHONEME_LIB[char]) output.push(char); // Fallback for raw codes

            i++;
        }
    }

    return output;
};

// 4. RUSSIAN (Placeholder)
const parseRussian = (text: string): string[] => {
    // Cyrillic to Phoneme mapping would go here
    return parseEnglish(text); // Fallback
};

// Main Router
const textToPhonemes = (text: string, language: VocalLanguage): string[] => {
    switch (language) {
        case VocalLanguage.PT_BR: return parsePortuguese(text);
        case VocalLanguage.EN_US: return parseEnglish(text);
        case VocalLanguage.JP: return parseJapanese(text);
        case VocalLanguage.RU: return parseRussian(text);
        default: return parsePortuguese(text);
    }
};

