import { 
  VocalPreset, VocalMode, VocalParams, SequencerNote, SequencerTrack, AudioPresetDefinition, PluginDefinition, SamplerConfig, VocalLanguage
} from '../types';

declare const lamejs: any;

// Constants
export const NOTE_FREQUENCIES: Record<string, number> = {
  'C': 16.35, 'C#': 17.32, 'D': 18.35, 'D#': 19.45, 'E': 20.60, 'F': 21.83,
  'F#': 23.12, 'G': 24.50, 'G#': 25.96, 'A': 27.50, 'A#': 29.14, 'B': 30.87
};

export const getFrequency = (note: string, octave: number): number => {
  const base = NOTE_FREQUENCIES[note] || 16.35;
  return base * Math.pow(2, octave);
};

export const midiToFreq = (midi: number): number => {
  return 440 * Math.pow(2, (midi - 69) / 12);
};

// --- AUDIO UTILS ---

export const decodeAudioData = async (ctx: AudioContext | OfflineAudioContext, base64: string): Promise<AudioBuffer> => {
    const binaryString = window.atob(base64.split(',')[1]);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return await ctx.decodeAudioData(bytes.buffer);
};

// Auto-Slicer based on Amplitude Threshold
export const detectSlices = (buffer: AudioBuffer, sensitivity: number): {start: number, end: number}[] => {
    const data = buffer.getChannelData(0);
    const step = Math.floor(buffer.sampleRate / 100); // 10ms resolution
    const slices = [];
    const threshold = 0.01 + ((1 - sensitivity) * 0.1); // Sensitivity maps 0..1 to threshold

    let isSilent = true;
    let startSample = 0;

    for(let i=0; i<data.length; i+=step) {
        // RMS of chunk
        let sum = 0;
        for(let j=0; j<step && i+j<data.length; j++) {
            sum += data[i+j] * data[i+j];
        }
        const rms = Math.sqrt(sum / step);

        if (isSilent && rms > threshold) {
            isSilent = false;
            startSample = i;
        } else if (!isSilent && rms < threshold) {
            isSilent = true;
            // End of slice
            if (i - startSample > step * 5) { // Min duration
                slices.push({
                    start: startSample / data.length,
                    end: i / data.length
                });
            }
        }
    }

    // Add final if not silent
    if (!isSilent) {
        slices.push({
            start: startSample / data.length,
            end: 1.0
        });
    }

    // If no slices detected, return full buffer
    if (slices.length === 0) return [{start: 0, end: 1}];

    return slices;
};

// --- ENCODING UTILS ---

export const bufferToMp3 = (buffer: AudioBuffer, bitrate: number): Blob => {
    if (typeof lamejs === 'undefined') {
        throw new Error("LameJS not found. Cannot encode MP3.");
    }

    const channels = buffer.numberOfChannels;
    const sampleRate = buffer.sampleRate;
    const mp3enc = new lamejs.Mp3Encoder(channels, sampleRate, bitrate);
    const left = buffer.getChannelData(0);
    const right = channels > 1 ? buffer.getChannelData(1) : left;

    // Convert float to int16 for LAME
    const sampleBlockSize = 1152;
    const mp3Data = [];

    // LAME expects Int16
    const l16 = new Int16Array(left.length);
    const r16 = new Int16Array(right.length);
    for(let i=0; i<left.length; i++) {
        l16[i] = Math.max(-1, Math.min(1, left[i])) * 32767;
        r16[i] = Math.max(-1, Math.min(1, right[i])) * 32767;
    }

    for (let i = 0; i < l16.length; i += sampleBlockSize) {
        const leftChunk = l16.subarray(i, i + sampleBlockSize);
        const rightChunk = r16.subarray(i, i + sampleBlockSize);
        let mp3buf;
        if (channels === 1) {
            mp3buf = mp3enc.encodeBuffer(leftChunk);
        } else {
            mp3buf = mp3enc.encodeBuffer(leftChunk, rightChunk);
        }
        if (mp3buf.length > 0) mp3Data.push(mp3buf);
    }

    const endBuf = mp3enc.flush();
    if (endBuf.length > 0) mp3Data.push(endBuf);

    return new Blob(mp3Data, { type: 'audio/mp3' });
};

// Helper: Convert AudioBuffer to WAV Blob with configurable Bit Depth
export const bufferToWav = (buffer: AudioBuffer, bitDepth: 8 | 16 | 32 = 16): Blob => {
  const numOfChan = buffer.numberOfChannels;
  const sampleRate = buffer.sampleRate;

  // 32-bit Float requires different format code (3) than PCM (1)
  const format = bitDepth === 32 ? 3 : 1; 

  // Calculate Size
  const bytesPerSample = bitDepth / 8;
  const blockAlign = numOfChan * bytesPerSample;
  const length = buffer.length * blockAlign + 44;

  const bufferArr = new ArrayBuffer(length);
  const view = new DataView(bufferArr);
  const channels = [];
  let i;
  let offset = 0;
  let pos = 0;

  // write RIFF chunk descriptor
  setUint32(0x46464952); // "RIFF"
  setUint32(length - 8); // file length - 8
  setUint32(0x45564157); // "WAVE"

  // write fmt sub-chunk
  setUint32(0x20746d66); // "fmt "
  setUint32(16); // length = 16
  setUint16(format); // 1 = PCM, 3 = IEEE Float
  setUint16(numOfChan);
  setUint32(sampleRate);
  setUint32(sampleRate * blockAlign); // avg. bytes/sec
  setUint16(blockAlign); // block-align
  setUint16(bitDepth); // bits per sample

  // write data sub-chunk
  setUint32(0x61746164); // "data"
  setUint32(length - pos - 4); // chunk length

  // Get channel data
  for (i = 0; i < buffer.numberOfChannels; i++)
    channels.push(buffer.getChannelData(i));

  // Write Interleaved Data
  let sample;
  while (pos < length) { // Check length instead of buffer.length loop to handle bytes correct
    // We iterate samples based on buffer length actually
    if (offset >= buffer.length) break;

    for (i = 0; i < numOfChan; i++) {
       // Get float sample -1 to 1
       sample = Math.max(-1, Math.min(1, channels[i][offset]));

       if (bitDepth === 8) {
           // 8-bit is unsigned 0..255, 128 is silence
           // scale to 0..255
           sample = ((sample * 0.5 + 0.5) * 255);
           view.setUint8(pos, sample);
           pos += 1;
       } 
       else if (bitDepth === 16) {
           // 16-bit is signed -32768..32767
           sample = (sample < 0 ? sample * 32768 : sample * 32767) | 0;
           view.setInt16(pos, sample, true);
           pos += 2;
       } 
       else if (bitDepth === 32) {
           // 32-bit Float
           view.setFloat32(pos, sample, true);
           pos += 4;
       }
    }
    offset++;
  }

  function setUint16(data: number) {
    view.setUint16(pos, data, true);
    pos += 2;
  }

  function setUint32(data: number) {
    view.setUint32(pos, data, true);
    pos += 4;
  }

  return new Blob([bufferArr], { type: 'audio/wav' });
};

/**
 * Convolution Reverb Generator (Space/Resonance Model)
 */
export const applyReverb = async (ctx: OfflineAudioContext, inputBuffer: AudioBuffer, mix: number, decayTime: number): Promise<AudioBuffer> => {
  if (mix <= 0) return inputBuffer;

  const sampleRate = ctx.sampleRate;
  const length = inputBuffer.length;

  // 1. Generate Impulse Response (Exponential Decay Noise)
  // Model: y(t) = Noise(t) * e^(-t / T)
  const irLength = sampleRate * decayTime;
  const irBuffer = ctx.createBuffer(1, irLength, sampleRate);
  const irData = irBuffer.getChannelData(0);

  for (let i = 0; i < irLength; i++) {
    // White noise * exponential decay
    irData[i] = (Math.random() * 2 - 1) * Math.pow(1 - (i / irLength), 4);
  }

  // 2. Convolve
  const convCtx = new OfflineAudioContext(1, length, sampleRate);
  const source = convCtx.createBufferSource();
  source.buffer = inputBuffer;

  const convolver = convCtx.createConvolver();
  convolver.buffer = irBuffer;
  convolver.normalize = true;

  const dryGain = convCtx.createGain();
  const wetGain = convCtx.createGain();

  dryGain.gain.value = 1 - (mix * 0.5);
  wetGain.gain.value = mix;

  source.connect(dryGain);
  dryGain.connect(convCtx.destination);

  source.connect(convolver);
  convolver.connect(wetGain);
  wetGain.connect(convCtx.destination);

  source.start();
  return await convCtx.startRendering();
};

