// --- RENDER ENGINE ---

export const renderVocals = async (
    ctx: AudioContext | OfflineAudioContext, 
    track: SequencerTrack, 
    bpm: number
): Promise<AudioBuffer> => {
    const sampleRate = ctx.sampleRate;
    const secondsPerBeat = 60 / bpm;

    // Calculate total duration
    let maxBeat = 0;
    track.notes.forEach(n => {
        if (n.startTime + n.duration > maxBeat) maxBeat = n.startTime + n.duration;
    });
    // Add 2 beats tail
    const totalSeconds = (maxBeat > 0 ? maxBeat + 2 : 4) * secondsPerBeat;
    const length = Math.ceil(totalSeconds * sampleRate);

    // Create Buffer
    const buffer = ctx.createBuffer(2, length, sampleRate);
    const left = buffer.getChannelData(0);
    const right = buffer.getChannelData(1);

    // Get Definition
    let def: AudioPresetDefinition = VOCAL_PRESETS_DATA[track.vocalParams.preset];
    if (track.vocalParams.preset === VocalPreset.CUSTOM || track.vocalParams.preset === VocalPreset.PLUGIN) {
        if (track.vocalParams.customData) def = track.vocalParams.customData;
    }

    // Default fallback if def is missing
    if (!def) def = VOCAL_PRESETS_DATA[VocalPreset.MALE_BR];

    // --- SAMPLER LOGIC ---
    if (track.vocalParams.preset === VocalPreset.SAMPLER && def.sampler?.sourceBase64) {
        try {
            // Check if Offline context can decode? OfflineContext might not support decodeAudioData in some envs perfectly without promise?
            // Usually we use a standard AudioContext for decoding.
            const tempCtx = new AudioContext();
            const rawBuffer = await decodeAudioData(tempCtx, def.sampler.sourceBase64);
            const rawData = rawBuffer.getChannelData(0);

            for (const note of track.notes) {
                const startSample = Math.floor(note.startTime * secondsPerBeat * sampleRate);
                const durationSample = Math.floor(note.duration * secondsPerBeat * sampleRate);

                // Determine Slice
                let sliceStart = 0;
                let sliceEnd = 1;
                const slices = def.sampler.slices || [{start:0, end:1}];

                if (def.sampler.mode === 'FNF_VOWEL' && def.sampler.vowelMap) {
                     const v = (note.lyric || 'a').toLowerCase();
                     const idx = def.sampler.vowelMap[v] ?? 0;
                     if (slices[idx]) {
                         sliceStart = slices[idx].start;
                         sliceEnd = slices[idx].end;
                     }
                } else if (def.sampler.mode === 'SEQUENCE') {
                    const idx = track.notes.indexOf(note) % slices.length;
                    sliceStart = slices[idx].start;
                    sliceEnd = slices[idx].end;
                } else {
                    const idx = def.sampler.activeSliceIndex || 0;
                    if (slices[idx]) {
                         sliceStart = slices[idx].start;
                         sliceEnd = slices[idx].end;
                    }
                }

                const sampleStartIdx = Math.floor(sliceStart * rawData.length);
                const sampleEndIdx = Math.floor(sliceEnd * rawData.length);

                // Pitch shift via resampling
                const rootFreq = midiToFreq(def.sampler.rootNote);
                const targetFreq = midiToFreq(note.midi + track.vocalParams.octaveShift * 12 + (def.sampler.detune/100));
                const rate = targetFreq / rootFreq;

                for(let i=0; i<durationSample; i++) {
                    const outPos = startSample + i;
                    if (outPos >= length) break;
                    const srcPos = sampleStartIdx + Math.floor(i * rate);
                    if (srcPos >= sampleEndIdx) break; // End of slice

                    const s = rawData[srcPos] || 0;
                    left[outPos] += s * track.volume;
                    right[outPos] += s * track.volume;
                }
            }
        } catch(e) { console.error("Sampler Error", e); }

        return buffer;
    }

    // --- SYNTH LOGIC ---
    for (const note of track.notes) {
        const startSample = Math.floor(note.startTime * secondsPerBeat * sampleRate);
        const durationSample = Math.floor(note.duration * secondsPerBeat * sampleRate);

        const freq = midiToFreq(note.midi + track.vocalParams.octaveShift * 12);

        // Basic Oscillator
        for(let i=0; i<durationSample; i++) {
             const pos = startSample + i;
             if (pos >= length) break;
             const t = i / sampleRate;
             const phase = t * freq * 2 * Math.PI;

             let val = 0;
             if (def.type === 'sine') val = Math.sin(phase);
             else if (def.type === 'square') val = Math.sign(Math.sin(phase));
             else if (def.type === 'sawtooth') val = 2 * (t * freq - Math.floor(t * freq + 0.5));
             else if (def.type === 'triangle') val = Math.abs(2 * (t * freq - Math.floor(t * freq + 0.5))) * 2 - 1;
             else if (def.type === 'pulse') val = (Math.sin(phase) > 0.5) ? 1.0 : -1.0;
             else val = Math.random() * 2 - 1; // Noise

             // Simple Envelope
             let env = 1;
             if (t < 0.01) env = t/0.01;
             const rem = (note.duration*secondsPerBeat) - (i/sampleRate);
             if (rem < 0.05) env = Math.max(0, rem/0.05);

             val *= env * track.volume * 0.5;

             left[pos] += val;
             right[pos] += val;
        }
    }

    return buffer;
};

export const renderProject = async (
    ctx: OfflineAudioContext, 
    tracks: SequencerTrack[], 
    bpm: number,
    sampleRate: number
): Promise<AudioBuffer> => {
    // Render individual tracks to buffers
    // We use a temporary context for track rendering to isolate them.
    // However, we want to respect the main length.

    const buffers = await Promise.all(tracks.map(async t => {
        if (t.muted) return null;
        // Create a temp offline context for this track
        // We need to know duration.
        // We reuse logic from renderVocals to determine length or just pass a large enough context.
        // Or simply, we pass a dummy context to renderVocals to get a buffer?
        // renderVocals uses ctx.createBuffer.

        // Let's pass the main ctx to createBuffer, but we fill it manually.
        // This effectively creates a new buffer for each track using the main context's factory method (safe).
        return await renderVocals(ctx, t, bpm);
    }));

    // Mix into main context
    // Since ctx is OfflineAudioContext, we schedule the buffers.
    buffers.forEach((buf, i) => {
        if (!buf) return;
        const track = tracks[i];

        const source = ctx.createBufferSource();
        source.buffer = buf;

        const gain = ctx.createGain();
        gain.gain.value = track.volume;

        if (tracks.some(tr => tr.solo)) {
            if (!track.solo) gain.gain.value = 0;
        }

        source.connect(gain);
        gain.connect(ctx.destination);
        source.start(0);
    });

    return await ctx.startRendering();
};
